static void omap_disconnect_pipelines ( struct drm_device * ddev ) { struct omap_drm_private * priv = ddev -> dev_private ; unsigned int i ; for ( i = 0 ; i < priv -> num_pipes ; i ++ ) { struct omap_drm_pipeline * pipe = & priv -> pipes [ i ] ; omapdss_device_disconnect ( NULL , pipe -> output ) ; omapdss_device_put ( pipe -> output ) ; pipe -> output = NULL ; } priv -> num_pipes = 0 ; } 